-- One row per sheet that has stored state of its own. A sheet without a row starts empty.
-- today: the sheet's "today" date; NULL means the real date.
CREATE TABLE sheet (
    id    VARCHAR(100) PRIMARY KEY,
    today DATE
);
-- The people on a sheet, listed in the order they were added (by id).
-- name: as entered, never blank; grade: one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL,
    name     VARCHAR(200) NOT NULL,
    grade    CHAR(1)      NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person's name is unique on the sheet, compared without regard to case. Names are stored
-- without surrounding spaces; name_key is the name as compared.
UPDATE person SET name = TRIM(name);
ALTER TABLE person ADD COLUMN name_key VARCHAR(200) GENERATED ALWAYS AS (LOWER(name));
CREATE UNIQUE INDEX person_sheet_name ON person (sheet_id, name_key);
-- A person's claims, listed newest first (by id, descending).
-- amount: 0.00 or more, two decimals; claim_date: defaults to the sheet's today; note: may be empty.
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)  NOT NULL,
    person_id  BIGINT        NOT NULL REFERENCES person (id),
    amount     DECIMAL(12, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE          NOT NULL,
    note       VARCHAR(1000) NOT NULL
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
-- The sheet's rate for each grade: a percent with two decimals. A grade without a row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(100)  NOT NULL,
    grade    CHAR(1)       NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(5, 2) NOT NULL CHECK (pct >= 0 AND pct <= 100),
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's status: DRAFT -> OPEN -> SETTLED, or DRAFT/OPEN -> VOID. SETTLED and VOID are final.
-- Only OPEN and SETTLED claims count toward the totals.
ALTER TABLE claim ADD COLUMN status VARCHAR(10) DEFAULT 'DRAFT' NOT NULL
    CHECK (status IN ('DRAFT', 'OPEN', 'SETTLED', 'VOID'));
